do $ctrl$
begin
  if not ((select count(*) from public.prompt_media m join v5_retrait r on r.id = m.prompt_id) = 0) then
    raise exception 'Lot 300 : une carte a retirer porte un visuel. Arret avant ecriture.';
  end if;
end $ctrl$;

update public.prompts p
set status = 'archived', updated_at = now()
from v5_retrait r
where p.id = r.id and p.status <> 'archived';

do $ctrl$
begin
  if not ((select count(*) from public.prompts p join v5_retrait r on r.id = p.id
        where p.status <> 'archived') = 0) then
    raise exception 'Lot 300 : des cartes visees par le retrait sont encore actives.';
  end if;
end $ctrl$;

commit;
